func runCLIForSetupTest(t *testing.T, args ...string) (string, string, error) {
	t.Helper()

	cmd := RootCmd()
	var stdout bytes.Buffer
	var stderr bytes.Buffer
	cmd.SetOut(&stdout)
	cmd.SetErr(&stderr)
	cmd.SetArgs(args)

	err := cmd.Execute()
	return stdout.String(), stderr.String(), err
}

func setupTestHome(t *testing.T) string {
	t.Helper()

	home := t.TempDir()
	t.Setenv("HOME", home)
	t.Setenv("STRADDLE_CONFIG", "")
	t.Setenv("STRADDLE_BASE_URL", "")
	t.Setenv("STRADDLE_TOKEN", "")
	return home
}

func writeSetupConfig(t *testing.T, home string, body string) string {
	t.Helper()

	path := filepath.Join(home, ".config", "straddle-pp-cli", "config.toml")
	if err := os.MkdirAll(filepath.Dir(path), 0o700); err != nil {
		t.Fatalf("creating config dir: %v", err)
	}
	if err := os.WriteFile(path, []byte(body), 0o600); err != nil {
		t.Fatalf("writing config: %v", err)
	}
	return path
}

func TestSetupCheckJSONLocalOnlyNoSecrets(t *testing.T) {
	home := setupTestHome(t)
	configPath := writeSetupConfig(t, home, "base_url = \"https://sandbox.straddle.com\"\ntoken = \"secret-token-value\"\n")

	stdout, stderr, err := runCLIForSetupTest(t, "setup", "check", "--json", "--config", configPath)
	if err != nil {
		t.Fatalf("setup check --json returned error: %v", err)
	}
	if stderr != "" {
		t.Fatalf("setup check --json wrote stderr: %q", stderr)
	}
	if strings.Contains(stdout, "secret-token-value") {
		t.Fatalf("setup check --json leaked token value:\n%s", stdout)
	}

	var got setupCheckResponse
	if err := json.Unmarshal([]byte(stdout), &got); err != nil {
		t.Fatalf("setup check --json emitted invalid JSON: %v\n%s", err, stdout)
	}
	if got.Command != "setup check" || !got.LocalPreview {
		t.Fatalf("setup command metadata mismatch: %#v", got)
	}
	if got.Config.Path != configPath || !got.Config.Loadable || !got.Config.Exists {
		t.Fatalf("config status mismatch: %#v", got.Config)
	}
	if got.Config.BaseURL != "https://sandbox.straddle.com" || got.Config.BaseURLSource != "config" {
		t.Fatalf("base_url status mismatch: %#v", got.Config)
	}
	if got.Environment.Classification != "sandbox" {
		t.Fatalf("environment classification = %q, want sandbox", got.Environment.Classification)
	}
	if !got.Auth.Configured || got.Auth.Source != "config" {
		t.Fatalf("auth source status mismatch: %#v", got.Auth)
	}
	if got.Safety["calls_straddle_api"] || got.Safety["calls_docs_endpoint"] || got.Safety["executes_mcp"] || got.Safety["posts_webhook"] || got.Safety["writes_production"] {
		t.Fatalf("setup check must report local-only safety flags, got %#v", got.Safety)
	}
	if !got.DocsSearch.LocalCommandAvailable || !got.SandboxGuide.LocalCommandAvailable {
		t.Fatalf("local companion command readiness missing: docs=%#v sandbox=%#v", got.DocsSearch, got.SandboxGuide)
	}
	for _, step := range []string{
		"straddle-pp-cli auth set-token --stdin",
		"straddle-pp-cli docs search \"charges\" --source commands --json",
		"straddle-pp-cli sandbox guide --json",
	} {
		if !containsSetupString(got.NextSteps, step) {
			t.Fatalf("next_steps missing %q: %#v", step, got.NextSteps)
		}
	}
	if !containsSetupString(got.NextSteps, "straddle-pp-cli doctor --json") {
		t.Fatalf("sandbox next_steps should include doctor: %#v", got.NextSteps)
	}
}

