func TestSetupCheckRejectsDeliverBeforeDelivery(t *testing.T) {
	var deliveryCount int
	server := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		deliveryCount++
		t.Fatalf("setup check should reject --deliver before posting delivery output")
	}))
	defer server.Close()

	home := setupTestHome(t)
	configPath := writeSetupConfig(t, home, "base_url = \"https://sandbox.straddle.com\"\n")

	oldArgs := os.Args
	t.Cleanup(func() {
		os.Args = oldArgs
	})
	os.Args = []string{
		"straddle-pp-cli",
		"setup",
		"check",
		"--config",
		configPath,
		"--deliver",
		"webhook:" + server.URL,
	}

	err := Execute()
	if err == nil {
		t.Fatalf("setup check should reject --deliver")
	}
	if !strings.Contains(err.Error(), "setup check does not support --deliver") {
		t.Fatalf("error should explain --deliver is unsupported, got %v", err)
	}
	if deliveryCount != 0 {
		t.Fatalf("delivery request count: want 0, got %d", deliveryCount)
	}
}

func containsSetupString(values []string, want string) bool {
	for _, value := range values {
		if value == want {
			return true
		}
	}
	return false
}
